void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = texture(iChannel0,fragCoord/iResolution.xy);
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec3 pattern(vec2 uv) {
    float l = step(0.5, fract(uv.y * 0.1 + iTime * 0.1 + 0.05 * length(sin(uv * 50.0))));
    vec2 p = fract(uv * 2.0) - 0.5;
    float x = 100.0, y = 100.0;

    for (int i = 0; i < 5; i++) {
        p = abs(p * 1.4) - 0.5;
        p *= rot(iTime * 0.1 + l);
        x = min(x, abs(p.x));
        y = min(y, abs(p.y));
    }

    vec3 col = mix(vec3(0.0, 0.2, 0.8), vec3(0.7, 0.15, 0.1), step(0.05, x));
    col = mix(col, vec3(0.8, 0.7, 0.1), step(0.1, y));
    col *= 2.0 - length(sin(uv * 500.0)) * 1.3;

    return mix(col, 0.7 - col * 1.5, l);
}

vec2 rand2(vec2 co) {
    return vec2(
        fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453),
        fract(cos(dot(co, vec2(4.898, 7.23))) * 23421.631)
    );
}

vec2 uniformDisc(vec2 co) {
    vec2 r = rand2(co);
    return sqrt(r.y) * vec2(cos(r.x * 6.283185), sin(r.x * 6.283185));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    uv += uniformDisc(uv + iTime * 0.1) / iResolution.xy * (1.0 + abs(uv.y + 0.25) * 7.0);
    uv /= 1.0 - uv.y * 1.5;
    uv *= rot(iTime * 0.05);

    vec3 col = pattern(uv);
    col = clamp(col, vec3(0.0), vec3(1.0));
    col *= 1.7 - fragCoord.y / iResolution.y * 1.3;
    col *= 1.0 + exp(-5.0 * length(uv)) * 0.5;
    col = mix(col * vec3(1.0, 0.8, 1.0), texture(iChannel0, fragCoord / iResolution.xy).rgb, 0.9);

    fragColor = vec4(col, 1.0);
}
